#!/usr/bin/env bash# Build both halves. Used on the gateway box, on Replit, and locally.set -euo pipefailcd "$(dirname "$0")"export BACKEND_URL="${BACKEND_URL:-http://127.0.0.1:8000}"echo "== backend venv"if [ ! -x backend/.venv/bin/python ] && [ ! -x backend/.venv/Scripts/python.exe ]; then  if ! python3 -m venv backend/.venv; then    echo "python3 -m venv failed. On Debian/Ubuntu: sudo apt install -y python3-venv   (then rerun build.sh)"    exit 1  fifiPY=backend/.venv/bin/python[ -x "$PY" ] || PY=backend/.venv/Scripts/python.exeecho "== backend deps""$PY" -m pip install --quiet --upgrade pip"$PY" -m pip install --quiet -r backend/requirements.txtecho "== frontend build"cd frontendnpm install --no-audit --no-fundnpm run buildecho "== build complete"